#include "ResourceManager.h"
#include "SecurityLogger.h"
#include "PermissionManager.h"
#include "Utils.h"
#include <iostream>
#include <fstream>
#include <limits>
#include <algorithm>
using namespace std;
ResourceManager::ResourceManager(SecurityLogger& securityLogger):logger(securityLogger){loadResources();}
void ResourceManager::saveResources() const {ofstream file(filename);if(!file){cout<<"Warning: Could not save resources.txt.\n";return;}for(const auto& r:resources)file<<r.getResourceID()<<" | "<<r.getClassification()<<" | "<<cleanField(r.getResourceName())<<'\n';}
void ResourceManager::loadResources(){ifstream file(filename);string line;int largest=0;while(getline(file,line)){auto f=splitLine(line);if(f.size()<3)continue;try{int id=stoi(f[0]);string level=f[1];if(level!="Public"&&level!="Internal"&&level!="Confidential")continue;resources.emplace_back(id,f[2],level);largest=max(largest,id);}catch(...){cout<<"Warning: Skipping invalid resource record.\n";}}nextResourceID=largest+1;}
const Resource* ResourceManager::findResourceByID(int id) const {for(const auto& r:resources)if(r.getResourceID()==id)return &r;return nullptr;}
void ResourceManager::addResource(){string name;int choice;cout<<"Enter resource name: ";getline(cin,name);name=trim(name);if(name.empty()){cout<<"Resource name cannot be empty.\n";return;}cout<<"1. Public\n2. Internal\n3. Confidential\nSelect: ";if(!(cin>>choice)){cin.clear();cin.ignore(numeric_limits<streamsize>::max(),'\n');cout<<"Invalid input.\n";return;}cin.ignore(numeric_limits<streamsize>::max(),'\n');if(choice<1||choice>3){cout<<"Invalid classification.\n";return;}string level=choice==1?"Public":choice==2?"Internal":"Confidential";int id=nextResourceID++;resources.emplace_back(id,name,level);saveResources();cout<<"Resource created and saved successfully.\n";resources.back().display();logger.logEvent("SYSTEM","System","RESOURCE_CREATED","SUCCESS");}
void ResourceManager::viewResources() const {if(resources.empty()){cout<<"No resources found.\n";return;}for(const auto& r:resources)r.display();}
void ResourceManager::searchResource() const {int id;cout<<"Enter Resource ID: ";if(!(cin>>id)){cin.clear();cin.ignore(numeric_limits<streamsize>::max(),'\n');cout<<"Invalid input.\n";return;}cin.ignore(numeric_limits<streamsize>::max(),'\n');const Resource* r=findResourceByID(id);if(!r){cout<<"Resource not found.\n";return;}r->display();}
void ResourceManager::deleteResource(){int id;cout<<"Enter Resource ID to delete: ";if(!(cin>>id)){cin.clear();cin.ignore(numeric_limits<streamsize>::max(),'\n');cout<<"Invalid input.\n";return;}cin.ignore(numeric_limits<streamsize>::max(),'\n');for(auto it=resources.begin();it!=resources.end();++it)if(it->getResourceID()==id){resources.erase(it);saveResources();logger.logEvent("SYSTEM","System","RESOURCE_DELETED","SUCCESS");cout<<"Resource deleted and changes saved.\n";return;}cout<<"Resource not found.\n";}
void ResourceManager::requestAccess(const User& user,const PermissionManager& permissions) const {viewResources();int id;cout<<"Enter Resource ID for access: ";if(!(cin>>id)){cin.clear();cin.ignore(numeric_limits<streamsize>::max(),'\n');logger.logEvent(user.getUsername(),user.getRole(),"RESOURCE_ACCESS:INVALID_INPUT","DENIED_INVALID_INPUT");cout<<"Invalid input.\n";return;}cin.ignore(numeric_limits<streamsize>::max(),'\n');const Resource* r=findResourceByID(id);if(!r){cout<<"Resource not found. Access denied.\n";logger.logEvent(user.getUsername(),user.getRole(),"RESOURCE_ACCESS:ID_"+to_string(id),"DENIED_NOT_FOUND");return;}string action;cout<<"Requested action (READ/WRITE/DELETE): ";getline(cin,action);transform(action.begin(),action.end(),action.begin(),[](unsigned char c){return static_cast<char>(toupper(c));});if(action!="READ"&&action!="WRITE"&&action!="DELETE"){cout<<"Invalid action.\n";logger.logEvent(user.getUsername(),user.getRole(),"RESOURCE_ACCESS:"+r->getResourceName(),"DENIED_INVALID_ACTION");return;}int denials=logger.countPreviousDeniedRequests(user.getUsername());int score=riskEngine.calculateRiskScore(user,*r,denials);string risk=riskEngine.getRiskLevel(score);riskEngine.displayRiskAssessment(score);logger.logEvent(user.getUsername(),user.getRole(),"RISK_ASSESSMENT:"+r->getResourceName(),"SCORE_"+to_string(score)+"_"+risk);bool allowed=permissions.isAllowed(user,*r,action);string event="RESOURCE_ACCESS:"+action+":"+r->getResourceName();if(allowed){cout<<"\nACCESS GRANTED for "<<action<<"\n";r->display();logger.logEvent(user.getUsername(),user.getRole(),event,"GRANTED");}else{cout<<"\nACCESS DENIED for "<<action<<"\nRole defaults or custom permission rules do not allow this action.\n";logger.logEvent(user.getUsername(),user.getRole(),event,"DENIED");}}
